document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("salary-period-form"),t=document.getElementById("salary-period-result");if(!e||!t)return;const r={year:1,month:12,week:52,day:260,hour:2080};e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("amount").value),o=document.getElementById("period").value;if(isNaN(n)||n<=0||!r[o])return t.innerHTML="<p>Please enter a valid salary amount and select a period.</p>",void 0;const a=n*("year"===o?1:r[o]),s={"per year":a,"per month":a/r.month,"per week":a/r.week,"per day":a/r.day,"per hour":a/r.hour},d=e=>e.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,",");let l="<h3>Salary Conversion Results:</h3><ul>";for(const[e,t]of Object.entries(s))l+=`<li><strong>${e}:</strong> $${d(t)}</li>`;l+="</ul>",l+="<div class='conversion-note'>",l+="<p><strong>Note:</strong> Calculations are based on standard full-time work:</p>",l+="<ul>",l+="<li>260 work days per year (52 weeks × 5 days)</li>",l+="<li>2,080 work hours per year (52 weeks × 40 hours)</li>",l+="</ul>",l+="<p><em>Results show gross salary before taxes and deductions.</em></p>",l+="</div>",t.innerHTML=l})});